// 배열 리터럴 → C 코드
private genArrayLiteral(node: ArrayLiteral): string {
  const elements = node.elements.map(e => this.genExpression(e)).join(', ');
  return `{${elements}}`;
}

// 배열 인덱싱 → C 코드
private genArrayAccess(node: ArrayAccess): string {
  const obj = this.genExpression(node.object);
  const idx = this.genExpression(node.index);
  return `${obj}[${idx}]`;
}

// 배열 메서드 → C 코드
private genArrayMethod(node: ArrayMethodCall): string {
  const obj = this.genExpression(node.object);

  switch (node.method) {
    case 'length':
      // C에서는 sizeof로 길이 계산
      return `(sizeof(${obj}) / sizeof(${obj}[0]))`;

    case 'push':
      // 동적 배열이 필요 (벡터 구현)
      const arg = this.genExpression(node.args[0]);
      return `vector_push(&${obj}, ${arg})`;

    case 'pop':
      return `vector_pop(&${obj})`;

    case 'first':
      return `${obj}[0]`;

    case 'last':
      return `${obj}[sizeof(${obj})/sizeof(${obj}[0])-1]`;

    default:
      throw new Error(`Unknown array method: ${node.method}`);
  }
}
```

